efinitive Guide |url=https://www.ign.com/articles/the-star-wars-canon-the-definitive-guide |access-date=2024-05-31 |website=IGN |language=en |archive-date=May 3, 2024 |archive-url=https://web.archive.org/web/20240503204025/https://www.ign.com/articles/the-star-wars-canon-the-definitive-guide |url-status=live }}</ref>}}

